(()=>{const records=JSON.parse(document.getElementById('op-records').textContent),range=document.getElementById('op-range'),chart=document.getElementById('op-chart'),detail=document.getElementById('op-detail');function show(id){const r=records.find(r=>r.id===id);detail.textContent='Injection '+r.id+' · '+r.time+' | Recycled '+r.recycled.toFixed(3)+' mL | Waste '+r.waste.toFixed(3)+' mL | Recycling '+(100*r.recycled/(r.recycled+r.waste)).toFixed(2)+'%';chart.querySelectorAll('[data-inj]').forEach(e=>e.setAttribute('opacity',+e.dataset.inj===id?'1':'.65'));}function draw(){const [a,b]=range.value.split(',').map(Number),items=records.filter(r=>r.id>=a&&r.id<=b),w=960/items.length,bw=Math.max(3,w-2),y=v=>270-v/13*230;let out='<svg viewBox="0 0 1040 320" role="group" aria-label="Recorded recycled and waste volume by injection, in millilitres">';for(const v of [0,4,8,12])out+='<path d="M50 '+y(v)+'H1010" stroke="#e0e7ed"/><text x="40" y="'+(y(v)+4)+'" text-anchor="end" font-size="12" fill="#607788">'+v+'</text>';items.forEach((r,i)=>{const x=50+i*w,total=r.recycled+r.waste;out+='<g data-inj="'+r.id+'" tabindex="0" role="button" aria-label="Injection '+r.id+', recycled '+r.recycled+' mL, waste '+r.waste+' mL" style="cursor:pointer"><rect x="'+x+'" y="'+y(r.recycled)+'" width="'+bw+'" height="'+(270-y(r.recycled))+'" fill="#0b3b60"/><rect x="'+x+'" y="'+y(total)+'" width="'+bw+'" height="'+(y(r.recycled)-y(total))+'" fill="#f58220"/><title>Injection '+r.id+': '+r.recycled+' mL recycled, '+r.waste+' mL waste</title></g>';if(i===0||i===items.length-1||(items.length<=25?r.id%5===0:r.id%10===0))out+='<text x="'+(x+bw/2)+'" y="290" text-anchor="middle" font-size="12" fill="#607788">'+r.id+'</text>';});out+='<text x="530" y="314" text-anchor="middle" fill="#0b3b60" font-size="13">Injection number · volume in mL</text></svg>';chart.innerHTML=out;chart.querySelectorAll('[data-inj]').forEach(e=>{['mouseenter','focus','click'].forEach(event=>e.addEventListener(event,()=>show(+e.dataset.inj)));e.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();show(+e.dataset.inj)}})});show(a)}range.addEventListener('change',draw);draw();})();